package hu.taliann.icesmp.classspec.application;

import hu.taliann.icesmp.classspec.domain.*;
import hu.taliann.icesmp.playerprofile.domain.section.ClassSpecSection;

import java.util.*;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionStage;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Function;
import java.util.function.Supplier;

/** Sole Profile v2 gateway with per-player serialization and session-generation fencing. */
public final class DefaultClassSpecProfileGateway implements ClassSpecProfileGateway {
    private final ClassSpecSectionMutationStore store;
    private final ClassSpecRuntimePort runtime;
    private final ProfileSessionRegistry sessions;
    private final ProfileMutationPolicy policy;
    private final Map<UUID,CompletableFuture<Void>> tails=new ConcurrentHashMap<>();
    private final Object admissionLock=new Object();
    private boolean accepting=true;

    public DefaultClassSpecProfileGateway(ClassSpecSectionMutationStore store,ClassSpecRuntimePort runtime,ProfileSessionRegistry sessions){this(store,runtime,sessions,new ProfileMutationPolicy());}
    DefaultClassSpecProfileGateway(ClassSpecSectionMutationStore store,ClassSpecRuntimePort runtime,ProfileSessionRegistry sessions,ProfileMutationPolicy policy){this.store=Objects.requireNonNull(store);this.runtime=Objects.requireNonNull(runtime);this.sessions=Objects.requireNonNull(sessions);this.policy=Objects.requireNonNull(policy);}
    public ProfileSessionRegistry sessions(){return sessions;}

    @Override public boolean isSessionReady(UUID id){Objects.requireNonNull(id);Optional<ClassSpecSection> p=store.cached(id);return sessions.isReady(id)&&p.isPresent()&&p.orElseThrow().isGameplayUsable()&&store.sessionBlockReason(id).isEmpty();}
    @Override public Optional<UUID> currentSessionToken(UUID id){return sessions.currentToken(Objects.requireNonNull(id));}
    @Override public boolean isCurrentSession(UUID id,UUID token){return sessions.isCurrent(Objects.requireNonNull(id),Objects.requireNonNull(token));}
    @Override public void beginSessionActivation(UUID id,UUID token){if(!sessions.isCurrent(id,token))throw new ProfileSessionRegistry.StaleSessionException(id,token);}
    @Override public void completeSessionActivation(UUID id,UUID token){sessions.markReady(id,token);}
    @Override public void cancelSessionActivation(UUID id,UUID token){sessions.close(id,token);}
    @Override public Optional<ClassSpecSection> currentProfile(UUID id){return store.cached(Objects.requireNonNull(id));}
    @Override public Optional<String> activeSpecId(UUID id){if(!isSessionReady(id))return Optional.empty();ClassSpecSection p=store.cached(id).orElseThrow();if(p.activeSlot()==null)return Optional.empty();ClassLoadout l=p.loadout(p.activeSlot());return l.status()==LoadoutStatus.ACTIVE?Optional.of(l.specializationId()):Optional.empty();}
    @Override public Optional<String> activeMechanic(UUID id,String key){String k=ClassSpecCatalog.normalize(key);if(!isSessionReady(id)||k.isEmpty())return Optional.empty();ClassSpecSection p=store.cached(id).orElseThrow();return p.activeSlot()==null?Optional.empty():Optional.ofNullable(p.loadout(p.activeSlot()).mechanicState().get(k));}
    @Override public Optional<CompanionProfile> activeCompanion(UUID id){if(!isSessionReady(id))return Optional.empty();ClassSpecSection p=store.cached(id).orElseThrow();if(p.activeSlot()==null)return Optional.empty();ClassLoadout l=p.loadout(p.activeSlot());String active=l.mechanicState().get("companion.active_id");if(active==null||active.isBlank())return Optional.empty();try{return Optional.ofNullable(l.companionRoster().get(UUID.fromString(active)));}catch(IllegalArgumentException ignored){store.blockSession(id,"Invalid active companion identity");return Optional.empty();}}
    @Override public Optional<ProfileOperation> operation(UUID id,String operationId){return store.cached(Objects.requireNonNull(id)).flatMap(profile->profile.operation(operationId));}
    @Override public ProfileDiagnostic diagnostic(UUID id){Optional<ClassSpecSection> p=store.cached(id);if(p.isEmpty()){Optional<String> q=store.quarantineReason(id);return q.isPresent()?ProfileDiagnostic.quarantined(q.orElseThrow()):ProfileDiagnostic.unavailable(store.sessionBlockReason(id).orElse("profile loading"));}return project(id,p.orElseThrow());}
    @Override public void blockSession(UUID id,String reason){String detail=reason==null||reason.isBlank()?"Profile v2 session blocked":reason.trim();store.blockSession(id,detail);sessions.currentToken(id).ifPresent(token->{if(sessions.isCurrent(id,token)){sessions.markReconciliationRequired(id,token,detail);try{runtime.failClosed(id,token,detail).whenComplete((ignored,failure)->{if(failure!=null)store.blockSession(id,detail+"; fail-closed cleanup failed: "+message(failure));});}catch(RuntimeException failure){store.blockSession(id,detail+"; fail-closed cleanup failed: "+message(failure));}}});}

    @Override public CompletionStage<ProfileMutationResult<ProfileDiagnostic>> select(UUID id,SelectRequest r){return mutate(id,ProfileMutationPolicy.Operation.SELECT,ClassSpecRuntimePort.MutationKind.SELECT,p->planSelection(p,r));}
    @Override public CompletionStage<ProfileMutationResult<ProfileDiagnostic>> switchLoadout(UUID id,SwitchRequest r){return mutate(id,ProfileMutationPolicy.Operation.LOADOUT_SWITCH,ClassSpecRuntimePort.MutationKind.LOADOUT_SWITCH,p->planSwitch(p,r));}
    @Override public CompletionStage<ProfileMutationResult<ProfileDiagnostic>> chooseDoctrine(UUID id,DoctrineChoiceRequest r){return mutate(id,ProfileMutationPolicy.Operation.DOCTRINE_CHOICE,ClassSpecRuntimePort.MutationKind.DOCTRINE_CHOICE,p->planDoctrine(p,r));}
    @Override public CompletionStage<ProfileMutationResult<ProfileDiagnostic>> contributeMastery(UUID id,MasteryContributionRequest r){return mutate(id,ProfileMutationPolicy.Operation.MASTERY_CONTRIBUTION,ClassSpecRuntimePort.MutationKind.MASTERY_CONTRIBUTION,p->planMastery(p,r));}
    @Override public CompletionStage<ProfileMutationResult<ProfileDiagnostic>> setCapstone(UUID id,CapstoneRequest r){return mutate(id,ProfileMutationPolicy.Operation.CAPSTONE_UPDATE,ClassSpecRuntimePort.MutationKind.CAPSTONE_UPDATE,p->planCapstone(p,r));}
    @Override public CompletionStage<ProfileMutationResult<ProfileDiagnostic>> assignClass(UUID id,ClassAssignmentRequest r){return mutate(id,ProfileMutationPolicy.Operation.CLASS_ASSIGN,ClassSpecRuntimePort.MutationKind.CLASS_ASSIGN,p->planClassAssignment(p,r));}
    @Override public CompletionStage<ProfileMutationResult<ProfileDiagnostic>> mutateClassExperience(UUID id,ClassExperienceRequest request){return mutate(id,ProfileMutationPolicy.Operation.CLASS_EXPERIENCE,ClassSpecRuntimePort.MutationKind.CLASS_EXPERIENCE,p->planClassExperience(p,request));}
    @Override public CompletionStage<ProfileMutationResult<ProfileDiagnostic>> seal(UUID id,SealRequest r){return mutate(id,ProfileMutationPolicy.Operation.EXPLICIT_SEAL,ClassSpecRuntimePort.MutationKind.EXPLICIT_SEAL,p->planSeal(p,r));}
    @Override public CompletionStage<ProfileMutationResult<ProfileDiagnostic>> reconcile(UUID id,ReconcileRequest r){return mutate(id,ProfileMutationPolicy.Operation.GATE_RECONCILE,ClassSpecRuntimePort.MutationKind.GATE_RECONCILE,p->planReconcile(p,r));}
    @Override public CompletionStage<ProfileMutationResult<ProfileDiagnostic>> reset(UUID id,ResetRequest r){return mutate(id,r.mode()==ResetMode.ADMIN_CLASS?ProfileMutationPolicy.Operation.ADMIN_RESET:ProfileMutationPolicy.Operation.LOADOUT_RESET,r.mode()==ResetMode.ADMIN_CLASS?ClassSpecRuntimePort.MutationKind.ADMIN_RESET:ClassSpecRuntimePort.MutationKind.RESPEC_RESET,p->planReset(p,r));}
    @Override public CompletionStage<ProfileMutationResult<ProfileDiagnostic>> incrementSoulforge(UUID id,String branch,int shardCost,String operationId){return mutate(id,ProfileMutationPolicy.Operation.SOULFORGE_UPGRADE,ClassSpecRuntimePort.MutationKind.SOULFORGE_UPGRADE,p->planSoulforge(p,branch,shardCost,operationId));}
    @Override public CompletionStage<ProfileMutationResult<ProfileDiagnostic>> mutateSoulShards(UUID id,int delta,String operationId){return mutate(id,ProfileMutationPolicy.Operation.SOUL_SHARD_MUTATION,ClassSpecRuntimePort.MutationKind.SOUL_SHARD_MUTATION,p->planSoulShards(p,delta,operationId));}
    @Override public CompletionStage<ProfileMutationResult<ProfileDiagnostic>> mutateCompanion(UUID id,CompanionMutationRequest r){return mutate(id,ProfileMutationPolicy.Operation.COMPANION_MUTATION,r.kind()==CompanionMutationRequest.Kind.PROGRESS?ClassSpecRuntimePort.MutationKind.COMPANION_PROGRESS:ClassSpecRuntimePort.MutationKind.COMPANION_MUTATION,p->planCompanion(p,r));}

    @Override public Optional<String> quarantineEvidenceId(UUID id){return store.quarantineEvidenceId(id);}
    @Override public CompletionStage<RecoveryResult> recoverQuarantined(UUID id,String evidenceId,String auditId){Objects.requireNonNull(id);String evidence=Objects.requireNonNull(evidenceId).trim(),audit=Objects.requireNonNull(auditId).trim();return enqueue(id,()->store.recover(id,evidence,audit).thenApply(profile->{store.blockSession(id,"Profile recovered; reconnect required before activation");sessions.currentToken(id).ifPresent(token->sessions.markReconciliationRequired(id,token,"Profile recovered; reconnect required"));return new RecoveryResult(profile,evidence,audit,audit.equals(profile.diagnostics().recoveryAuditId()));}));}
    @Override public CompletionStage<Void> awaitPlayerMutations(UUID id){CompletableFuture<Void> t=tails.get(id);return t==null?CompletableFuture.completedFuture(null):t.handle((v,x)->null);}
    @Override public CompletionStage<Void> prepareShutdown(){CompletableFuture<?>[] pending;synchronized(admissionLock){accepting=false;pending=tails.values().toArray(CompletableFuture[]::new);}sessions.stop();return CompletableFuture.allOf(pending);}
    @Override public void clearSession(UUID id){CompletableFuture<Void> t=tails.get(id);if(t!=null)t.whenComplete((v,x)->tails.remove(id,t));}

    private CompletionStage<ProfileMutationResult<ProfileDiagnostic>> mutate(UUID id,ProfileMutationPolicy.Operation operation,ClassSpecRuntimePort.MutationKind kind,Function<ClassSpecSection,Plan> planner){Objects.requireNonNull(id);Optional<UUID> token=sessions.currentToken(id);if(token.isEmpty())return CompletableFuture.completedFuture(ProfileMutationResult.rejected(diagnostic(id),"no active Profile v2 session"));UUID captured=token.orElseThrow();return enqueue(id,()->perform(id,captured,operation,kind,planner));}
    private CompletionStage<ProfileMutationResult<ProfileDiagnostic>> perform(UUID id,UUID token,ProfileMutationPolicy.Operation operation,ClassSpecRuntimePort.MutationKind kind,Function<ClassSpecSection,Plan> planner){if(!sessions.isCurrent(id,token))return CompletableFuture.completedFuture(ProfileMutationResult.rejected(diagnostic(id),"stale session before mutation"));Optional<ClassSpecSection> loaded=store.cached(id);if(loaded.isEmpty())return CompletableFuture.completedFuture(ProfileMutationResult.rejected(diagnostic(id),"profile is not loaded"));ClassSpecSection previous=loaded.orElseThrow();ProfileMutationPolicy.Decision access=policy.assess(previous,store.sessionBlockReason(id),operation);if(!access.allowed())return CompletableFuture.completedFuture(ProfileMutationResult.rejected(project(id,previous),access.detail()));Plan plan;try{plan=Objects.requireNonNull(planner.apply(previous));}catch(IllegalArgumentException|IllegalStateException x){return CompletableFuture.completedFuture(ProfileMutationResult.rejected(project(id,previous),x.getMessage()));}if(plan.candidate==null)return CompletableFuture.completedFuture(plan.rejected?ProfileMutationResult.rejected(project(id,previous),plan.detail):ProfileMutationResult.noChange(project(id,previous),plan.detail));ClassSpecSection candidate=plan.candidate;if(candidate.revision()!=NumericGuards.nextRevision(previous.revision()))return CompletableFuture.completedFuture(ProfileMutationResult.rejected(project(id,previous),"mutation must increment revision exactly once"));CompletionStage<ClassSpecSectionMutationStore.SaveResult> save;try{save=Objects.requireNonNull(store.save(id,previous.revision(),candidate));}catch(RuntimeException x){return persistenceFailure(id,token,previous,ProfileMutationResult.Status.PERSISTENCE_FAILED,message(x));}return save.handle(SaveCompletion::new).thenCompose(done->{if(done.failure!=null)return persistenceFailure(id,token,previous,ProfileMutationResult.Status.PERSISTENCE_FAILED,message(done.failure));ClassSpecSectionMutationStore.SaveResult result=done.result;ClassSpecSection durable=result.durableProfile()==null?previous:result.durableProfile();return switch(result.status()){case COMMITTED->afterCommit(id,token,previous,result.durableProfile(),kind);case REVISION_CONFLICT->persistenceFailure(id,token,durable,ProfileMutationResult.Status.REVISION_CONFLICT,result.detail());case PERSISTENCE_FAILED->persistenceFailure(id,token,durable,ProfileMutationResult.Status.PERSISTENCE_FAILED,result.detail());case LIFECYCLE_STOPPED->CompletableFuture.completedFuture(ProfileMutationResult.failed(project(id,durable),ProfileMutationResult.Status.LIFECYCLE_STOPPED,result.detail()));};});}
    private CompletionStage<ProfileMutationResult<ProfileDiagnostic>> afterCommit(UUID id,UUID token,ClassSpecSection previous,ClassSpecSection durable,ClassSpecRuntimePort.MutationKind kind){if(!sessions.isCurrent(id,token))return CompletableFuture.completedFuture(ProfileMutationResult.stale(project(id,durable),"durable commit completed for a retired session; runtime effects fenced"));CompletionStage<Void> effect;try{effect=Objects.requireNonNull(runtime.profileCommitted(id,token,previous,durable,kind));}catch(RuntimeException x){effect=CompletableFuture.failedFuture(x);}return effect.handle((v,x)->{if(x==null)return ProfileMutationResult.committed(project(id,durable));String detail="durable commit succeeded but runtime reconciliation failed: "+message(x);store.blockSession(id,detail);if(sessions.isCurrent(id,token))sessions.markReconciliationRequired(id,token,detail);return ProfileMutationResult.failed(project(id,durable),ProfileMutationResult.Status.RUNTIME_EFFECT_FAILED,detail);});}
    private CompletionStage<ProfileMutationResult<ProfileDiagnostic>> persistenceFailure(UUID id,UUID token,ClassSpecSection durable,ProfileMutationResult.Status status,String detail){store.blockSession(id,detail);if(sessions.isCurrent(id,token))sessions.markReconciliationRequired(id,token,detail);CompletionStage<Void> cleanup;try{cleanup=runtime.failClosed(id,token,detail);}catch(RuntimeException x){cleanup=CompletableFuture.failedFuture(x);}return cleanup.handle((v,x)->ProfileMutationResult.failed(project(id,durable),status,x==null?detail:detail+"; fail-closed cleanup also failed: "+message(x)));}

    private Plan planClassAssignment(ClassSpecSection p,ClassAssignmentRequest r){String clazz=ClassSpecCatalog.normalize(r.classId());if(!ClassSpecCatalog.isKnownClass(clazz))return Plan.reject("unknown class: "+clazz);if(!p.primaryClassId().isEmpty())return p.primaryClassId().equals(clazz)?Plan.no("class already assigned"):Plan.reject("profile already has another class");if(r.classLevel()>ClassSpecSection.MAX_CLASS_LEVEL)return Plan.reject("class level exceeds supported range");return Plan.of(p.toBuilder().revision(NumericGuards.nextRevision(p.revision())).primaryClassId(clazz).classLevel(r.classLevel()).classExperience(r.classExperience()).build());}
    private Plan planClassExperience(ClassSpecSection p,ClassExperienceRequest r){if(p.primaryClassId().isEmpty())return Plan.reject("classless profile cannot mutate experience");Optional<ProfileOperation> existing=p.operation(r.operationId());if(existing.isPresent())return replay(existing.orElseThrow(),ProfileOperationType.CLASS_EXPERIENCE,r.mode().name(),Integer.toString(r.value()),"class_xp","class experience");final int next;try{next=r.mode()==ClassExperienceRequest.Mode.ADD?Math.addExact(p.classExperience(),r.value()):r.value();}catch(ArithmeticException overflow){return Plan.reject("class experience overflow");}if(next<0)return Plan.reject("class experience cannot be negative");int level=levelForExperience(next,r.baseXp(),r.incrementPerLevel());boolean second=p.secondSpecUnlocked()||(GameplayV2ClassPolicy.isEnabled(p.primaryClassId())&&level>=r.secondSpecUnlockLevel());ClassSpecSection candidate=p.toBuilder().revision(NumericGuards.nextRevision(p.revision())).classExperience(next).classLevel(level).secondSpecUnlocked(second).build();ProfileOperation receipt=new ProfileOperation(r.operationId(),ProfileOperationType.CLASS_EXPERIENCE,ProfileOperationStatus.COMMITTED,r.mode().name(),Integer.toString(r.value()),"class_xp",p.revision(),"class experience committed");return Plan.of(withReceipt(candidate,receipt));}
    private Plan planSelection(ClassSpecSection p,SelectRequest r){String spec=ClassSpecCatalog.normalize(r.specializationId());if(!ClassSpecCatalog.isKnownSpecialization(spec)||!ClassSpecCatalog.belongsTo(spec,p.primaryClassId()))return Plan.reject("specialization does not belong to primary class");if(DarkSpecializationPolicy.isDark(spec)&&!r.gates().state().allSatisfied())return Plan.reject("DARK specialization gates are not satisfied");if(r.slot()==LoadoutSlot.SECOND&&!GameplayV2ClassPolicy.isEnabled(p.primaryClassId()))return Plan.reject("second-slot gameplay is enabled only for reworked classes: "+GameplayV2ClassPolicy.enabledList());if(r.slot()==LoadoutSlot.SECOND&&!p.secondSpecUnlocked())return Plan.reject("second slot locked");if(p.loadout(r.slot()).status()!=LoadoutStatus.EMPTY)return Plan.reject("target loadout is not empty");if(p.loadouts().stream().anyMatch(x->spec.equals(x.specializationId())))return Plan.reject("specialization already exists");boolean activate=p.activeSlot()==null;ClassLoadout loadout=new ClassLoadout(spec,activate?LoadoutStatus.ACTIVE:LoadoutStatus.INACTIVE,null,Map.of(),MasteryProgress.empty(),null,Set.of(),"",CapstoneStatus.LOCKED,Map.of(),Map.of(),"");return Plan.of(p.toBuilder().revision(NumericGuards.nextRevision(p.revision())).loadout(r.slot(),loadout).activeSlot(activate?r.slot():p.activeSlot()).build());}
    private Plan planSwitch(ClassSpecSection p,SwitchRequest r){if(!GameplayV2ClassPolicy.isEnabled(p.primaryClassId()))return Plan.reject("loadout switching is enabled only for reworked classes: "+GameplayV2ClassPolicy.enabledList());LoadoutSlot targetSlot=r.slot();ClassLoadout target=p.loadout(targetSlot);if(target.status()==LoadoutStatus.EMPTY)return Plan.reject("target loadout is empty");if(target.status()==LoadoutStatus.SEALED)return Plan.reject("target loadout is sealed");if(p.activeSlot()==targetSlot)return Plan.no("loadout already active");if(target.status()!=LoadoutStatus.INACTIVE)return Plan.reject("target loadout is not inactive");ClassSpecSection.Builder b=p.toBuilder().revision(NumericGuards.nextRevision(p.revision())).loadout(targetSlot,target.withStatus(LoadoutStatus.ACTIVE,null)).activeSlot(targetSlot);if(p.activeSlot()!=null){ClassLoadout current=p.loadout(p.activeSlot());if(current.status()!=LoadoutStatus.ACTIVE)return Plan.reject("current active slot is inconsistent");b.loadout(p.activeSlot(),current.withStatus(LoadoutStatus.INACTIVE,null));}return Plan.of(b.build());}
    private Plan planDoctrine(ClassSpecSection p,DoctrineChoiceRequest r){ClassLoadout current=p.loadout(r.slot());if(current.status()==LoadoutStatus.EMPTY||current.status()==LoadoutStatus.SEALED)return Plan.reject("doctrine loadout is unavailable");String tier=ClassSpecCatalog.normalize(r.tier()),choice=ClassSpecCatalog.normalize(r.choice()),existing=current.doctrineChoices().get(tier);if(choice.equals(existing))return Plan.no("doctrine choice already committed");if(existing!=null)return Plan.reject("doctrine tier already has a different choice");return Plan.of(p.toBuilder().revision(NumericGuards.nextRevision(p.revision())).loadout(r.slot(),current.withDoctrineChoice(tier,choice)).build());}
    private Plan planMastery(ClassSpecSection p,MasteryContributionRequest r){if(p.activeSlot()!=r.slot())return Plan.reject("mastery contribution requires the active loadout");ClassLoadout current=p.loadout(r.slot());if(current.status()!=LoadoutStatus.ACTIVE)return Plan.reject("mastery contribution requires an active specialization");final long total;try{total=Math.addExact(current.mastery().experience(),r.experience());}catch(ArithmeticException overflow){return Plan.reject("mastery experience overflow");}int rank=(int)Math.min(MasteryProgress.MAX_RANK,total/r.experiencePerRank());if(rank==current.mastery().rank()&&total==current.mastery().experience())return Plan.no("mastery unchanged");return Plan.of(p.toBuilder().revision(NumericGuards.nextRevision(p.revision())).loadout(r.slot(),current.withMastery(new MasteryProgress(rank,total))).build());}
    private Plan planCapstone(ClassSpecSection p,CapstoneRequest r){ClassLoadout current=p.loadout(r.slot());if(current.status()==LoadoutStatus.EMPTY||current.status()==LoadoutStatus.SEALED)return Plan.reject("capstone loadout is unavailable");CapstoneStatus previous=current.capstoneStatus(),next=r.status();if(previous==next)return Plan.no("capstone state already set");if(previous==CapstoneStatus.COMPLETED||next.ordinal()<previous.ordinal())return Plan.reject("capstone state cannot move backwards");return Plan.of(p.toBuilder().revision(NumericGuards.nextRevision(p.revision())).loadout(r.slot(),current.withCapstoneStatus(next)).build());}
    private Plan planReset(ClassSpecSection p,ResetRequest r){Optional<ProfileOperation> existing=p.operation(r.operationId());if(existing.isPresent())return replay(existing.orElseThrow(),ProfileOperationType.RESPEC,r.mode().name(),r.amount(),r.currencyId().isEmpty()?"none":r.currencyId(),"reset");ClassSpecSection candidate;if(r.mode()==ResetMode.ADMIN_CLASS){if(p.primaryClassId().isEmpty())return Plan.no("profile already classless");candidate=p.withoutClass();}else{LoadoutSlot slot=r.slot().orElseThrow();if(p.loadout(slot).status()==LoadoutStatus.EMPTY)return Plan.no("loadout already empty");candidate=p.toBuilder().revision(NumericGuards.nextRevision(p.revision())).loadout(slot,ClassLoadout.empty()).activeSlot(p.activeSlot()==slot?null:p.activeSlot()).build();}ProfileOperation receipt=new ProfileOperation(r.operationId(),ProfileOperationType.RESPEC,ProfileOperationStatus.COMMITTED,r.mode().name(),r.amount(),r.currencyId().isEmpty()?"none":r.currencyId(),p.revision(),"profile reset committed");return Plan.of(withReceipt(candidate,receipt));}
    private static int levelForExperience(int experience,int baseXp,int increment){int level=1,remaining=experience;while(level<ClassSpecSection.MAX_CLASS_LEVEL){final int cost;try{cost=Math.addExact(baseXp,Math.multiplyExact(level-1,increment));}catch(ArithmeticException overflow){throw new IllegalArgumentException("class level curve overflow",overflow);}if(remaining<cost)break;remaining-=cost;level++;}return level;}
    private Plan planSoulforge(ClassSpecSection p,String rawBranch,int shardCost,String operationId){String opId=operationId==null?"":operationId.trim();if(opId.isEmpty())return Plan.reject("operationId is required");if(shardCost<=0)return Plan.reject("Soulforge shard cost must be positive");String branch=ClassSpecCatalog.normalize(rawBranch);if(!Set.of("elet","sebzes","letszam").contains(branch))return Plan.reject("unknown Soulforge branch");Optional<ProfileOperation> existing=p.operation(opId);if(existing.isPresent())return replay(existing.orElseThrow(),ProfileOperationType.SOULFORGE_UPGRADE,branch,Integer.toString(shardCost),"soul_shard","Soulforge");if(p.activeSlot()==null)return Plan.reject("Soulforge requires active necromancer");LoadoutSlot slot=p.activeSlot();ClassLoadout current=p.loadout(slot);if(current.status()!=LoadoutStatus.ACTIVE||!"necromancer".equals(current.specializationId()))return Plan.reject("Soulforge requires active necromancer");String rankKey="necromancer.soulforge."+branch,shardKey="necromancer.soulforge.shards";int rank,shards;try{rank=Integer.parseInt(current.mechanicState().getOrDefault(rankKey,"0"));shards=Integer.parseInt(current.mechanicState().getOrDefault(shardKey,"0"));}catch(NumberFormatException x){return Plan.reject("invalid Soulforge numeric state");}if(rank<0||rank>=5)return Plan.reject(rank>=5?"Soulforge branch maxed":"invalid Soulforge rank");if(shards<shardCost)return Plan.reject("insufficient soul shards");Map<String,String> mechanics=new LinkedHashMap<>(current.mechanicState());mechanics.put(rankKey,Integer.toString(Math.addExact(rank,1)));mechanics.put(shardKey,Integer.toString(Math.subtractExact(shards,shardCost)));ClassSpecSection candidate=p.toBuilder().revision(NumericGuards.nextRevision(p.revision())).loadout(slot,current.withMechanicState(mechanics)).build();return Plan.of(withReceipt(candidate,new ProfileOperation(opId,ProfileOperationType.SOULFORGE_UPGRADE,ProfileOperationStatus.COMMITTED,branch,Integer.toString(shardCost),"soul_shard",p.revision(),"rank and shard debit committed atomically")));}
    private Plan planSoulShards(ClassSpecSection p,int delta,String operationId){if(delta==0)return Plan.no("zero soul shard delta");String opId=operationId==null?"":operationId.trim();if(opId.isEmpty())return Plan.reject("operationId is required");Optional<ProfileOperation> existing=p.operation(opId);if(existing.isPresent())return replay(existing.orElseThrow(),ProfileOperationType.SOUL_SHARD_MUTATION,"shards",Integer.toString(delta),"soul_shard","soul shard");if(p.activeSlot()==null)return Plan.reject("soul shards require active necromancer");LoadoutSlot slot=p.activeSlot();ClassLoadout current=p.loadout(slot);if(current.status()!=LoadoutStatus.ACTIVE||!"necromancer".equals(current.specializationId()))return Plan.reject("soul shards require active necromancer");String key="necromancer.soulforge.shards";int currentAmount;try{currentAmount=Integer.parseInt(current.mechanicState().getOrDefault(key,"0"));}catch(NumberFormatException x){return Plan.reject("invalid soul shard state");}int next;try{next=Math.addExact(currentAmount,delta);}catch(ArithmeticException x){return Plan.reject("soul shard overflow");}if(next<0)return Plan.reject("insufficient soul shards");Map<String,String> mechanics=new LinkedHashMap<>(current.mechanicState());mechanics.put(key,Integer.toString(next));ClassSpecSection candidate=p.toBuilder().revision(NumericGuards.nextRevision(p.revision())).loadout(slot,current.withMechanicState(mechanics)).build();return Plan.of(withReceipt(candidate,new ProfileOperation(opId,ProfileOperationType.SOUL_SHARD_MUTATION,ProfileOperationStatus.COMMITTED,"shards",Integer.toString(delta),"soul_shard",p.revision(),"soul shard balance committed")));}
    private Plan planCompanion(ClassSpecSection p,CompanionMutationRequest r){Optional<ProfileOperation> existing=p.operation(r.operationId());if(existing.isPresent())return replay(existing.orElseThrow(),ProfileOperationType.COMPANION_MUTATION,r.kind().name(),"0","none","companion");ClassLoadout current=p.loadout(r.slot());if(current.status()==LoadoutStatus.EMPTY||current.status()==LoadoutStatus.SEALED)return Plan.reject("companion loadout is unavailable");Map<UUID,CompanionProfile> roster=new LinkedHashMap<>(current.companionRoster());Map<String,String> mechanics=new LinkedHashMap<>(current.mechanicState());UUID id=r.companionId();switch(r.kind()){case ADD->{if(r.companion()==null)return Plan.reject("companion payload required");if(!Objects.equals(ClassSpecCatalog.companionNamespace(current.specializationId()),r.companion().namespace()))return Plan.reject("companion namespace does not belong to loadout");if(r.capacity()>0&&roster.size()>=r.capacity())return Plan.reject("companion roster is full");if(roster.putIfAbsent(r.companion().companionId(),r.companion())!=null)return Plan.reject("companion already exists");mechanics.put("companion.active_id",r.companion().companionId().toString());}case REMOVE->{if(id==null||roster.remove(id)==null)return Plan.no("companion absent");if(id.toString().equals(mechanics.get("companion.active_id")))mechanics.remove("companion.active_id");}case DISMISS->{if(mechanics.remove("companion.active_id")==null)return Plan.no("companion already dismissed");}case SET_ACTIVE->{if(id==null||!roster.containsKey(id))return Plan.reject("unknown companion");if(id.toString().equals(mechanics.get("companion.active_id")))return Plan.no("companion already active");mechanics.put("companion.active_id",id.toString());}case RENAME->{CompanionProfile c=requiredCompanion(roster,id);roster.put(id,c.withName(r.text()));}case STANCE->{CompanionProfile c=requiredCompanion(roster,id);roster.put(id,c.withStance(r.text()));}case PROGRESS->{CompanionProfile c=requiredCompanion(roster,id);roster.put(id,c.withProgress(r.level(),r.experience()));}case EQUIPMENT->{CompanionProfile c=requiredCompanion(roster,id);roster.put(id,c.withEquipment(r.equipment()));}case STATE->{CompanionProfile c=requiredCompanion(roster,id);roster.put(id,c.withPersistentState(r.state()));}case RESPAWN_AT->{CompanionProfile c=requiredCompanion(roster,id);roster.put(id,c.withResummonAt(r.resummonAtEpochMillis()));}}ClassSpecSection candidate=p.toBuilder().revision(NumericGuards.nextRevision(p.revision())).loadout(r.slot(),new ClassLoadout(current.specializationId(),current.status(),current.sealReason(),current.doctrineChoices(),current.mastery(),current.soulbond(),current.favoriteSpells(),current.selectedSpell(),current.capstoneStatus(),roster,mechanics,current.diagnosticNote())).build();return Plan.of(withReceipt(candidate,new ProfileOperation(r.operationId(),ProfileOperationType.COMPANION_MUTATION,ProfileOperationStatus.COMMITTED,r.kind().name(),"0","none",p.revision(),"companion mutation committed")));}
    private static CompanionProfile requiredCompanion(Map<UUID,CompanionProfile> roster,UUID id){if(id==null||!roster.containsKey(id))throw new IllegalArgumentException("unknown companion");return roster.get(id);}
    private Plan planSeal(ClassSpecSection p,SealRequest r){ClassLoadout current=p.loadout(r.slot());if(current.status()==LoadoutStatus.EMPTY)return Plan.reject("empty loadout cannot be sealed");if(current.status()==LoadoutStatus.SEALED)return current.sealReason().equals(r.reason())?Plan.no("already sealed"):Plan.reject("existing seal requires explicit recovery");return Plan.of(p.toBuilder().revision(NumericGuards.nextRevision(p.revision())).loadout(r.slot(),current.withStatus(LoadoutStatus.SEALED,r.reason())).activeSlot(p.activeSlot()==r.slot()?null:p.activeSlot()).build());}
    private Plan planReconcile(ClassSpecSection p,ReconcileRequest r){EnumMap<LoadoutSlot,ClassLoadout> replacements=new EnumMap<>(LoadoutSlot.class);LoadoutSlot active=p.activeSlot();for(LoadoutSlot slot:LoadoutSlot.values()){ClassLoadout current=p.loadout(slot);if(current.status()==LoadoutStatus.EMPTY||!DarkSpecializationPolicy.isDark(current.specializationId()))continue;GateSnapshot gates=r.gatesBySlot().get(slot);if(gates==null)return Plan.reject("missing DARK gate snapshot");SealReason missing=gates.missingReason();if(missing!=null){if(current.status()==LoadoutStatus.SEALED&&!current.sealReason().gateRestorableOnly())continue;if(current.status()==LoadoutStatus.SEALED&&current.sealReason().equals(missing))continue;replacements.put(slot,current.withStatus(LoadoutStatus.SEALED,missing));if(active==slot)active=null;}else if(current.status()==LoadoutStatus.SEALED&&current.sealReason().gateRestorableOnly()&&gates.authorizesRecovery(current.sealReason()))replacements.put(slot,current.withStatus(LoadoutStatus.INACTIVE,null));}if(replacements.isEmpty())return Plan.no("gate state already reconciled");ClassSpecSection.Builder b=p.toBuilder().revision(NumericGuards.nextRevision(p.revision())).activeSlot(active);for(var e:replacements.entrySet())b.loadout(e.getKey(),e.getValue());return Plan.of(b.build());}
    private static Plan replay(ProfileOperation operation,ProfileOperationType expectedType,String target,String amount,String currency,String label){ProfileOperation expected=new ProfileOperation(operation.operationId(),expectedType,operation.status(),target,amount,currency,operation.startedRevision(),operation.detail());if(operation.type()!=expected.type()||!operation.target().equals(expected.target())||!operation.amount().equals(expected.amount())||!operation.currencyId().equals(expected.currencyId()))return Plan.reject(label+" operation id was reused with different parameters");return operation.status()==ProfileOperationStatus.COMMITTED?Plan.no(label+" operation already committed"):Plan.reject(label+" operation is pending recovery");}
    private static ClassSpecSection withReceipt(ClassSpecSection p,ProfileOperation receipt){Map<String,ProfileOperation> ops=new LinkedHashMap<>(p.operations());if(ops.size()>=ClassSpecSection.MAX_OPERATION_RECEIPTS&&!ops.containsKey(receipt.operationId())){String oldest=ops.values().stream().filter(o->o.status()!=ProfileOperationStatus.PENDING).min(Comparator.comparingLong(ProfileOperation::startedRevision).thenComparing(ProfileOperation::operationId)).map(ProfileOperation::operationId).orElseThrow(()->new IllegalStateException("operation ledger full with pending receipts"));ops.remove(oldest);}ops.put(receipt.operationId(),receipt);return p.toRecoveryBuilder().operations(ops).build();}
    private ProfileDiagnostic project(UUID id,ClassSpecSection p){EnumMap<LoadoutSlot,ProfileDiagnostic.SlotDiagnostic> slots=new EnumMap<>(LoadoutSlot.class);for(LoadoutSlot s:LoadoutSlot.values()){ClassLoadout l=p.loadout(s);slots.put(s,new ProfileDiagnostic.SlotDiagnostic(text(l.specializationId()),l.status(),Optional.ofNullable(l.sealReason()),l.mastery().rank(),l.mastery().experience()));}String block=store.sessionBlockReason(id).orElseGet(()->sessions.session(id).filter(s->s.state()!=ProfileSessionRegistry.State.READY).map(ProfileSessionRegistry.Session::detail).orElse(""));String review=p.status()==ProfileStatus.REVIEW?p.diagnostics().sessionBlockReason():"";return new ProfileDiagnostic(true,true,p.schemaVersion(),p.revision(),p.status(),text(p.primaryClassId()),p.classLevel(),p.classExperience(),Optional.ofNullable(p.activeSlot()),p.secondSpecUnlocked(),slots,text(review),text(p.diagnostics().quarantineReason()),text(block.isBlank()?p.diagnostics().sessionBlockReason():block));}
    private <T>CompletionStage<T> enqueue(UUID id,Supplier<CompletionStage<T>> operation){CompletableFuture<Void> gate=new CompletableFuture<>(),previous;synchronized(admissionLock){if(!accepting)return CompletableFuture.failedFuture(new IllegalStateException("Profile mutation lifecycle stopped"));previous=tails.put(id,gate);}CompletionStage<Void> start=previous==null?CompletableFuture.completedFuture(null):previous.handle((v,x)->null);CompletableFuture<T> result=new CompletableFuture<>();start.thenCompose(v->{try{return Objects.requireNonNull(operation.get());}catch(Throwable x){return CompletableFuture.failedFuture(x);}}).whenComplete((v,x)->{if(x==null)result.complete(v);else result.completeExceptionally(x);gate.complete(null);tails.remove(id,gate);});return result;}
    private static Optional<String> text(String v){return v==null||v.isBlank()?Optional.empty():Optional.of(v.trim());}private static String message(Throwable x){Throwable c=x;while(c instanceof java.util.concurrent.CompletionException&&c.getCause()!=null)c=c.getCause();return c.getMessage()==null?c.getClass().getSimpleName():c.getMessage();}
    private record Plan(ClassSpecSection candidate,boolean rejected,String detail){static Plan of(ClassSpecSection p){return new Plan(Objects.requireNonNull(p),false,"");}static Plan no(String d){return new Plan(null,false,d);}static Plan reject(String d){return new Plan(null,true,d);}}
    private record SaveCompletion(ClassSpecSectionMutationStore.SaveResult result,Throwable failure){}
}
